//! Table tests of what reads the static type of an `Exponentiate` or a `MultiplyGroup` node. sigmastate types
//! both `GroupElement` whatever their operands are (v6.0.6 `trees.scala:1028-1031`, `:1050-1053`: both mix in
//! `NotReadyValueGroupElement`, `values.scala:755-757`), and both parsers build them over a left operand of any
//! type. So a parse check, a `val`, a branch, a tuple item or a method call around such a node sees a group
//! element, also where the left operand is typed `Any` or `Int`.
//!
//! The rows are sigma-state 6.0.7's (the round's `measure/rows/sel.txt`, `out/jvm-sel-*.txt`; generated by
//! `measure/tests/gen_rows_test.py`): the node over a left operand that is `Any`-typed with a group element as
//! its value (`anyge`), an `Int` constant (`int`), `Any`-typed with an `Int` as its value (`anyint`) or a group
//! element (`ctl`), in an operand slot of another node (`slot`) or in a consumer written for a group element
//! (`hand`), and each again as `if (true) true else { val v = <row>; false }` (`twin`), which is `true` exactly
//! where the row parses. A row of tree version 0 has the same answer at activated versions 2 and 3 and is run
//! at both; a row of tree version 3 is run at 3.
//!
//! The `cons` rows are the review's (`rows/cons2.txt`): the node over `if (false) 1 else g` (`lie`: statically an
//! `Int`, a group element at evaluation) under 60 more consumers, and under `Global.some[GroupElement]`. The
//! `right` rows (`rows/right.txt`) type the RIGHT operand `Any` or `Int`: the node's type does not follow it
//! either. The last tables are trees on a node's path (`rows/ctx.txt`, `reduce_to_crypto`): a script read by
//! `DeserializeContext` or `DeserializeRegister` is checked against the declared type before anything is
//! evaluated, also in a branch never taken, and an absent register's default is put in unchecked and its
//! ancestors are built again around it.
use crate::eval::reduce_to_crypto;
use crate::eval::test_util::jvm_text;
use crate::eval::{Env, Evaluable};
use alloc::boxed::Box;
use ergotree_ir::chain::context::Context;
use ergotree_ir::chain::context_extension::ContextExtension;
use ergotree_ir::chain::ergo_box::ErgoBox;
use ergotree_ir::ergo_tree::ErgoTree;
use ergotree_ir::ergo_tree::ErgoTreeVersion;
use ergotree_ir::mir::expr::Expr;
use ergotree_ir::serialization::sigma_byte_reader::from_bytes;
use ergotree_ir::serialization::sigma_byte_reader::SigmaByteRead;
use ergotree_ir::serialization::SigmaSerializable;
use ergotree_ir::sigma_protocol::sigma_boolean::SigmaBoolean;
use sigma_test_util::force_any_val;

/// A row: its name in the round's row set, the expression's bytes, the tree version, then `REFUSED` where the
/// parser refuses the expression, `ERR` where its evaluation fails or the value as `jvm_text` prints it, and
/// the cost counter where the evaluation ended (0 for a refusal)
type Row = (&'static str, &'static str, u8, &'static str, u64);

/// The runs whose outcome, value or cost counter is not the table's, and the number of runs: a row runs once
/// at each activated version it has
#[allow(clippy::unwrap_used)]
fn wrong_runs(rows: &[Row]) -> (alloc::vec::Vec<alloc::string::String>, usize) {
    let mut wrong = alloc::vec::Vec::new();
    let mut runs = 0;
    for (name, body, version, expected, cost) in rows {
        let activated_versions: &[i8] = if *version == 0 { &[2, 3] } else { &[3] };
        let version = ErgoTreeVersion::from(*version);
        let bytes = base16::decode(body.as_bytes()).unwrap();
        for activated in activated_versions {
            runs += 1;
            let (got, stopped_at) =
                match from_bytes(&bytes).with_tree_version(version, Expr::sigma_parse) {
                    Err(_) => ("REFUSED".into(), 0),
                    Ok(expr) => {
                        let mut ctx = force_any_val::<Context>();
                        ctx.activated_script_version_byte = *activated;
                        ctx.tree_version.set(version);
                        ctx.jit_cost.set(0);
                        let got = match expr.eval(&mut Env::empty(), &ctx) {
                            Ok(v) => jvm_text(&v),
                            Err(_) => "ERR".into(),
                        };
                        (got, ctx.jit_cost_value())
                    }
                };
            if got != *expected || stopped_at != *cost {
                wrong.push(alloc::format!(
                    "{name} (activated {activated}): expected {expected} at {cost}, got {got} at {stopped_at}"
                ));
            }
        }
    }
    (wrong, runs)
}

fn assert_rows(rows: &[Row]) {
    let (wrong, runs) = wrong_runs(rows);
    assert!(
        wrong.is_empty(),
        "{} of {} runs:\n{}",
        wrong.len(),
        runs,
        wrong.join("\n")
    );
}

/// A tree on a node's path: its name, the tree's bytes, the self box's bytes and the context extension's bytes
/// (a `DeserializeContext` reads variable 1, a `DeserializeRegister` the box's R4; R5 is absent), then
/// `REJECTED` where the tree is refused at the read, `true` or `false` for the proposition it reduces to, `ERR`
/// where the reduction fails, and the cost of a reduction that succeeds (0 otherwise). Activated version 3.
type PathRow = (
    &'static str,
    &'static str,
    &'static str,
    &'static str,
    &'static str,
    u64,
);

#[allow(clippy::unwrap_used)]
fn assert_paths(rows: &[PathRow]) {
    let mut wrong = alloc::vec::Vec::new();
    for (name, tree, self_box, extension, expected, cost) in rows {
        let tree = from_bytes(&base16::decode(tree.as_bytes()).unwrap()).with_versions(
            ErgoTreeVersion::V3,
            ErgoTreeVersion::V3,
            ErgoTree::sigma_parse,
        );
        let (got, got_cost) = match tree {
            Err(_) => ("REJECTED", 0),
            Ok(tree) => {
                let self_box = from_bytes(&base16::decode(self_box.as_bytes()).unwrap())
                    .with_versions(
                        ErgoTreeVersion::V3,
                        ErgoTreeVersion::V3,
                        ErgoBox::sigma_parse,
                    )
                    .unwrap();
                let extension = ContextExtension::sigma_parse_bytes(
                    &base16::decode(extension.as_bytes()).unwrap(),
                )
                .unwrap();
                let mut ctx = force_any_val::<Context>();
                ctx.self_box = Box::leak(Box::new(self_box));
                ctx.extension = Box::leak(Box::new(extension));
                ctx.activated_script_version_byte = 3;
                ctx.jit_cost.set(0);
                ctx.jit_cost_limit = Some(100_000_000);
                match reduce_to_crypto(&tree, &ctx) {
                    Ok(r) => match r.sigma_prop {
                        SigmaBoolean::TrivialProp(true) => ("true", r.cost),
                        SigmaBoolean::TrivialProp(false) => ("false", r.cost),
                        _ => ("<prop>", r.cost),
                    },
                    Err(_) => ("ERR", 0),
                }
            }
        };
        if got != *expected || got_cost != *cost {
            wrong.push(alloc::format!(
                "{name}: expected {expected} at {cost}, got {got} at {got_cost}"
            ));
        }
    }
    assert!(
        wrong.is_empty(),
        "{} of {}:\n{}",
        wrong.len(),
        rows.len(),
        wrong.join("\n")
    );
}

